# Buat folder untuk setiap tahun
2013..2021 | ForEach-Object {
    $folderName = $_.ToString()
    if (-not (Test-Path $folderName)) {
        New-Item -ItemType Directory -Path $folderName
        Write-Host "Folder $folderName dibuat"
    }
}

# Pindahkan file berdasarkan tahun dalam nama file
Get-ChildItem -Filter "*.xls" | ForEach-Object {
    if ($_.Name -match '\d{4}') {
        $year = $matches[0]
        $destination = Join-Path $year $_.Name
        Move-Item -Path $_.FullName -Destination $destination
        Write-Host "Memindahkan $($_.Name) ke folder $year"
    }
}

Write-Host "Selesai!"

const wbook = SpreadsheetApp.getActive()

function doGet() {
  const sheet = wbook.getSheetByName("B");
  //B merupakan nama sheet yang digunakan, diganti dengan sheet yang akan digunakan
  let data = [];
  const rlen = sheet.getLastRow();
  const clen = sheet.getLastColumn();
  const rows = sheet.getRange(1,1,rlen,clen).getValues();

  for(let i = 0; i < rows.length; i++){
    const dataRow = rows[i];
    let record = {};
    for (let j=0; j<clen; j++){
      record[rows[0][j]] = dataRow[j];
    }

    if(i > 0){
      data.push(record);
    }
  }

  const response = {
    "data": data
  }

  return ContentService.createTextOutput(JSON.stringify(response)).setMimeType(ContentService.MimeType.JSON);
}
